package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 记录更正请求：绑定主体、用途、代次、记录键与期望版本，成功后追加完整新 payload 并使版本加一。
 *
 * @param requestId             幂等请求标识
 * @param subjectKey            主体标识（合成字符串）
 * @param purpose               用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch                 记录所属授权代次，必须当前有效，从 1 开始
 * @param recordKey             记录键
 * @param payload               更正后的完整记录内容（合成字符串），最长 1000 字符
 * @param expectedRecordVersion 期望的当前记录版本，初版为 1；与当前版本不符返回 409
 */
public record CorrectRecordRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotNull @Min(1) Integer epoch,
        @NotBlank @Size(max = 128) String recordKey,
        @NotBlank @Size(max = 1000) String payload,
        @NotNull @Min(1) Integer expectedRecordVersion) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;

/**
 * 记录版本响应：更正结果与历史读取均返回指定版本的完整内容。
 *
 * @param subjectKey    主体标识（合成字符串）
 * @param purpose       用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch         记录所属授权代次
 * @param recordKey     记录键
 * @param recordVersion 记录版本，从 1 开始，每次更正加一
 * @param payload       该版本的完整记录内容（合成字符串）
 */
public record RecordVersionResponse(String subjectKey, Purpose purpose, int epoch, String recordKey,
                                    int recordVersion, String payload) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;

/**
 * 记录元数据响应：只返回代次与版本号，不返回 payload；撤回后仍可查询。
 *
 * @param subjectKey    主体标识（合成字符串）
 * @param purpose       用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch         记录所属授权代次
 * @param recordKey     记录键
 * @param recordVersion 当前记录版本，从 1 开始
 */
public record RecordMetadataResponse(String subjectKey, Purpose purpose, int epoch, String recordKey,
                                     int recordVersion) {
}

